import re

def week_buckets(items, path):
    def get_monday(date_str):
        date = datetime.strptime(date_str, '%Y-%m-%d')
        return (date - timedelta(days=date.weekday())).strftime('%Y-%m-%d')

    def valid_date(date_str):
        try:
            datetime.strptime(date_str, '%Y-%m-%d')
            return True
        except ValueError:
            return False

    def valid_item(item):
        parts = item.split('|', 1)
        if len(parts) != 2 or not valid_date(parts[0].strip()) or not parts[1].strip():
            return False
        return True

    events = {}
    for item in items:
        if valid_item(item):
            date, event = item.split('|', 1)
            date = date.strip()
            event = event.strip()
            monday = get_monday(date)
            if monday not in events:
                events[monday] = []
            if event not in events[monday]:
                events[monday].append(event)

    with open(os.path.dirname(path) + '/' + os.path.basename(path), 'w', encoding='utf-8') as f:
        for monday in sorted(events.keys()):
            f.write(f'{monday}|{",".join(events[monday])}\n')
